sys_script_include.script:
var DecisionV2Utils = Class.create();
DecisionV2Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getDecisionResults: function() {
        var u_id = this.getParameter('u_id');
		var dtAPI = new sn_dt.DecisionTableAPI();

        var inputs = {
            'u_id': u_id, // 機能ID输入列
        };
        var dtSysId = '3Dfe3fc51d0f1b3a147409c9c530d1b215'; // 你的决策表sys_id（必填）
        var result = dtAPI.executeDecisionTable(dtSysId, inputs);

        var output = {};
        if (result && result.outputs) {
            output.u_pattenrn_1 = result.outputs.u_pattenrn_1 || '';
            output.step2_1 = result.outputs.step2_1 || ''; // Step2-1对应输出列
            output.success = true;
        } else {
            output.success = false;
            output.message = '決策表に一致するルールが存在しません';
        }

        return JSON.stringify(output);

        },

    getEmployeeInfo: function() {
        var userGr = new GlideRecord('sys_user');
        var name = this.getParameter('user');
        /*if ("" == user_name) {
            user_name = gs.getUserName();
        }*/
        userGr.get(name);

        var configuration = {};	
        //configuration.employee_number = userGr.employee_number + ''; //社員番号
        configuration.name = userGr.name + ''; //氏名
        configuration.email = userGr.email + ''; //メールアドレス

        return JSON.stringify(configuration);
    },


    type: 'DecisionV2Utils'
});
